import{Mt as e,ft as t,mt as n,n as r}from"./chunks/framework.CLZVGDxv.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"en/update.md","filePath":"en/update.md"}`),a={name:`en/update.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="ai-yinmei-v2-4-2" tabindex="-1">Ai Yinmei v2.4.2 <a class="header-anchor" href="#ai-yinmei-v2-4-2" aria-label="Permalink to “Ai Yinmei v2.4.2”">​</a></h2><h3 id="new-features" tabindex="-1">New Features: <a class="header-anchor" href="#new-features" aria-label="Permalink to “New Features:”">​</a></h3><ol><li><p>QQ Group Super Administrator Mute: Sending profanities such as &quot;your mother,&quot; &quot;eat shit,&quot; or &quot;fuck you&quot; will result in varying degrees of mute. Mute words can be customized through vector caching.</p></li><li><p>QQ Group Super Administrator Recall: 1. Configuring keywords via vector caching in a plugin format. 2. Recalling advertisements and links through keyword-based full matching.</p></li><li><p>Fixed some issues with the QQ group&#39;s interactive layout, such as the &quot;tap to view&quot; feature appearing in the background.</p></li><li><p>Administrators and super administrators can control and manage certain group numbers and whitelist certain QQ accounts.</p></li><li><p>Image Context Association: Optimized the previous limitation that image analysis could only be performed within the same message body as text; now it can be set to associate with a certain number of context images.</p></li><li><p>Fixed the issue of QQ group globally shared messages being overwritten and ineffective. QQ group globally monitored messages are now effective, and the number of context images to be monitored can be set.</p></li></ol><h3 id="current-qq-robot-capabilities" tabindex="-1">Current QQ Robot Capabilities: <a class="header-anchor" href="#current-qq-robot-capabilities" aria-label="Permalink to “Current QQ Robot Capabilities:”">​</a></h3><ol><li><p>Message Recall</p></li><li><p>Mute messages for a period of time. 3. Ability to reply to chat, reply to knowledge manuals, and search for information.</p></li><li><p>Ability to analyze the context of multiple images.</p></li><li><p>Ability to search for and post videos on Bilibili.</p></li><li><p>Ability to search for and post images.</p></li><li><p>Ability to send voice messages.</p></li><li><p>Ability to sing.</p></li></ol><h2 id="ai-yinmei-v2-4-1" tabindex="-1">Ai Yinmei v2.4.1 <a class="header-anchor" href="#ai-yinmei-v2-4-1" aria-label="Permalink to “Ai Yinmei v2.4.1”">​</a></h2><h3 id="new-features-1" tabindex="-1">New Features: <a class="header-anchor" href="#new-features-1" aria-label="Permalink to “New Features:”">​</a></h3><ol><li><p>Inputting free keys via LLM [Completed]</p></li><li><p>Reconnecting to the bullet screen button [Under testing]</p></li><li><p>OpenAI specification TTS [Completed]</p></li><li><p>Merging chats, queuing and summarizing chats every 10 seconds.</p></li><li><p>Dynamic routing of pre-tasks for customizable processes.</p></li><li><p>WeChat live streaming [Under development]</p></li><li><p>Multi-camera vision integration, multi-eye observation.</p></li></ol><h3 id="optimized-features" tabindex="-1">Optimized Features: <a class="header-anchor" href="#optimized-features" aria-label="Permalink to “Optimized Features:”">​</a></h3><ol><li><p>Singing FastAPI [Completed]</p></li><li><p>Vector caching with a switch.</p></li><li><p>BERT VTS2 compatibility with 2.4 Yinmei [Completed]</p></li><li><p>Separation of chat and function call models.</p></li><li><ol start="6"><li>Added separators to speech synthesis to speed up speech [Completed]</li></ol></li><li><p>Optimized some parameter settings for vision during glm [Completed]</p></li></ol><h2 id="ai-yinmei-v2-4-0-2026-02-04" tabindex="-1">Ai Yinmei v2.4.0 [2026-02-04] <a class="header-anchor" href="#ai-yinmei-v2-4-0-2026-02-04" aria-label="Permalink to “Ai Yinmei v2.4.0 [2026-02-04]”">​</a></h2><h3 id="new-features-2" tabindex="-1">New Features: <a class="header-anchor" href="#new-features-2" aria-label="Permalink to “New Features:”">​</a></h3><p><strong>1. VL Vision:</strong> Large model tools intelligently recognize vision, intent analysis recognizes vision, etc., allowing AI to recognize a video, an image, content on a screen, camera content, etc., a versatile vision system.</p><p>Regular patrols allow AI to continuously monitor your screen, allowing it to continuously accompany you while playing games.</p><p><strong>2. Super Aggregated Bullet Screen:</strong> Integrated with Douyin, Kuaishou, Douyu, Huya, plus the previous Bilibili, desktop pets, QQ robots, and backend systems, a total of 8 channels.</p><p><strong>3. Integration with New Voice Synthesis [cosyvoice2]:</strong> **Built-in clones of Mambo, Ma Baoguo, Cai Xukun, Crazy Mita, Beef AI, and other voices, customizable 3-second cloned voices, and configurable emotional tags, resulting in highly human-like voice synthesis. A super-emotional speech synthesis system with VLLM acceleration and fine-tuning of the underlying model, achieving a first syllable speed of 600 milliseconds.</p><p><strong>4. Baidu Translate:</strong> More accurate, utilizing AI translation capabilities.</p><p><strong>5. Singing:</strong> Added facial expression control.</p><p><strong>6. Desktop Pet:</strong> Added a simple microphone mode [no character loading] and [memory-saving lightweight mode] to the desktop pet. When starting VTS, the microphone function can also be used for conversation.</p><p><strong>7. Character Activity:</strong> XY-axis frequency jump function makes the swaying motion more dynamic. This effect will be reflected in singing and chatting.</p><p><strong>8. Publicly Available Lottery System:</strong> [1] Conduct independent lottery draws based on point deductions. [2] The host conducts a group lottery in the live broadcast room the host controls the flow</p><p><strong>9. Prompt word compression technology:</strong> This technology can reduce token loss while improving the understanding speed of the LLM model, ensuring semantic integrity.</p><p><strong>10. Multi-person AI interaction function:</strong> Multiple AIs can chat with each other, supporting remote interaction.</p><h3 id="public-capabilities" tabindex="-1">Public capabilities: <a class="header-anchor" href="#public-capabilities" aria-label="Permalink to “Public capabilities:”">​</a></h3><ol><li><p>25 large model tool plugins: Timed patrol, visual capabilities, image search, greeting operation, Wikipedia, TMDB movie rating website, browser manipulation, calculator, query user points, advanced search, thought chain, product information query, stock tool, time zone conversion, random number, cooking guide, changing character clothing, character movement and rotation, speech synthesis switch, speech speed adjustment, AI dancing, AI singing, AI painting, search tool</p></li><li><p>Lottery function: Autonomous lottery, group lottery</p></li><li><p>Intent analysis training: Customize intent classification, allowing multiple personalities to adapt to more different emotions, diversifying language, facial expressions, voice tone, and the operation of MCP and large model tools.</p></li></ol><h3 id="optimized-features-1" tabindex="-1">Optimized Features: <a class="header-anchor" href="#optimized-features-1" aria-label="Permalink to “Optimized Features:”">​</a></h3><p><strong>1. Yinmei Black Technology:</strong> True Streaming AI Voice Interaction [Full-Link Streaming] Speech Recognition [The only drawback is that streaming speech recognition in LLM makes segmented understanding impossible] -&gt; LLM Streaming -&gt; Speech Synthesis Model Generation Streaming -&gt; Network Audio Transmission Streaming -&gt; Player Streaming</p><p>This is true streaming TTS.</p><p><strong>2. Speech Synthesis Acceleration Optimization:</strong> Cosyvoice2 synthesis speed improved to 0.6 seconds first packet response time, gpt-sovits synthesis speed improved to 0.4 seconds first packet response time, achieving full-streaming speech synthesis.</p><p><strong>3. XY Axis Jump:</strong> Setting the xy-axis to 0 indicates the function is off; program initialization does not trigger xy-axis reset.</p><p><strong>4. Background Chat Interface:</strong> Live streaming can be made into an aggregated bullet screen mode [Bilibili, Douyin, Kuaishou, Douyu, Huya, Yinmei Desktop Pets, Backend, API]</p><p><strong>5. Extended Hints for Interface Request Parameters:</strong></p><p>enable_search is the Alibaba Bailian search switch, web_search is the Zhipu search switch. <code>enable_thinking</code> is the Alibaba Deep Thinking switch, and <code>thinking</code> is the Zhipu Deep Thinking switch.</p><p><strong>6. QQ Robot Display Mode:</strong> To avoid the risk of being banned by Tencent, using the global mode is the safest. Using the segmented mode will output a sentence in segments, and if the output density is too high, it will be banned by the Tencent system. [Global mode cannot send voice messages, only text.]</p><p><strong>7. Batch Switch Function List:</strong> One-click import of all default functions for users to choose from.</p><p><strong>8. Chat Interface:</strong> Markdown syntax is displayed in a friendly manner, supporting line breaks, etc.</p><p><strong>9. Optimization and Acceleration of Large Model Tools and MCP Tools:</strong> Vector caching has been added to accelerate tool call speed. 25 large model tools can be called simultaneously without lag, with a 5x improvement in response speed.</p><p><strong>10. Desktop Pet Dialogue Supports Built-in Funasr:</strong> No additional installation is required, improving ease of use. Continuous Conversation Made Easier</p><h3 id="process-optimization" tabindex="-1">Process Optimization: <a class="header-anchor" href="#process-optimization" aria-label="Permalink to “Process Optimization:”">​</a></h3><ol><li><p>Optimized and accelerated workflow for large model tools and MCP tools: Added vector caching, supporting asynchronous tool calls.</p></li><li><p>Optimized workflow conflicts between intent analysis and large model tools.</p></li><li><p>Container version + Windows version for speech synthesis.</p></li><li><p>Training can be operated through the intent analysis interface.</p></li></ol><h2 id="ai-yinmei-v2-3-0-2025-7-15" tabindex="-1">Ai Yinmei v2.3.0 [2025-7-15] <a class="header-anchor" href="#ai-yinmei-v2-3-0-2025-7-15" aria-label="Permalink to “Ai Yinmei v2.3.0 [2025-7-15]”">​</a></h2><h3 id="_1-intelligent-capabilities-yinmei-can-access-thought-chains-advanced-search-product-information-query-stock-tools-time-zone-conversion-random-numbers-cooking-guides-ai-singing-drawing-and-dancing-speech-speed-adjustment-video-search-and-playback-character-movement-and-rotation-changing-character-clothing-wikipedia-and-calculator" tabindex="-1">1. Intelligent Capabilities: Yinmei can access thought chains, advanced search, product information query, stock tools, time zone conversion, random numbers, cooking guides, AI singing, drawing, and dancing, speech speed adjustment, video search and playback, character movement and rotation, changing character clothing, Wikipedia, and calculator. <a class="header-anchor" href="#_1-intelligent-capabilities-yinmei-can-access-thought-chains-advanced-search-product-information-query-stock-tools-time-zone-conversion-random-numbers-cooking-guides-ai-singing-drawing-and-dancing-speech-speed-adjustment-video-search-and-playback-character-movement-and-rotation-changing-character-clothing-wikipedia-and-calculator" aria-label="Permalink to “1. Intelligent Capabilities: Yinmei can access thought chains, advanced search, product information query, stock tools, time zone conversion, random numbers, cooking guides, AI singing, drawing, and dancing, speech speed adjustment, video search and playback, character movement and rotation, changing character clothing, Wikipedia, and calculator.”">​</a></h3><p><strong>Thought Chains:</strong> When you ask Yinmei to think about how China can defeat the United States, or to seriously consider assembling an 8000 yuan AI computer for you, or to analyze which three A-share stocks to buy next week using thought chains, Yinmei will activate thought chains for continuous thinking.</p><p><strong>Advanced Search:</strong> Ask her to find today&#39;s latest news, check the weather in a certain area, ask about recent breakthroughs in quantum technology, and see what new artificial intelligence technologies are emerging.</p><p><strong>Product Information Inquiry:</strong> Ask Yinmei for a price quote on a 5070ti graphics card. Yinmei will check prices on Pinduoduo and JD.com. You can ask her to find three Pinduoduo stores with high-performance graphics cards at competitive prices.</p><p><strong>Stock Tools:</strong> [Stock Prices, Information, Stock Analyst Advice] Ask Yinmei to analyze the recent trend of a stock code or name to determine if it&#39;s worth buying.</p><p><strong>Random Numbers:</strong> [Can generate random names, numbers, etc.] Ask Yinmei to create five random names, generate three security keys, or predict tomorrow&#39;s fortune.</p><p><strong>Cooking Guide:</strong> Ask Yinmei to teach you how to cook and recommend what to eat for dinner and breakfast.</p><p><strong>AI Singing, Drawing, and Dancing Intelligence:</strong> Ask Yinmei to recommend new anime songs for July and find the most popular female vocal songs of the year.</p><p><strong>Speech Speed Adjustment:</strong> Make her speak quickly, speak very quickly, speak a little faster, speak slowly, speak very slowly, etc.</p><p><strong>Video search and playback:</strong> Searches for videos on Bilibili, which will then play on the monitor. Let Yinmei find you the silliest videos of Xiang Zuo, etc.</p><p><strong>Character Movement and Rotation:</strong> Make Yinmei move left, right, up, and down; make her fly; make her burrow underground; make her run fast; make her spin in circles, up to 10 circles (maximum 10 circles).</p><p><strong>Changing Character Clothing:</strong> Make Yinmei dress sexier; make her wear glasses, etc.</p><p><strong>TMDB Movie Ratings:</strong> Let Yinmei recommend highly-rated new movies.</p><p><strong>Calculator:</strong> Basic calculation functions.</p><p><strong>Check User Points:</strong> Let Yinmei check your points.</p><p><strong>Wikipedia:</strong> Detailed queries for certain knowledge points.</p><p><strong>Browser Control:</strong> Can control Google Chrome.</p><h3 id="_2-gpt-sovits2-pro-plus-upgrade" tabindex="-1">2. GPT-Sovits2 Pro Plus Upgrade: <a class="header-anchor" href="#_2-gpt-sovits2-pro-plus-upgrade" aria-label="Permalink to “2. GPT-Sovits2 Pro Plus Upgrade:”">​</a></h3><p>Yinmei is now compatible with the entire GPT-Sovits1~4+Pro+Pro Plus series. Synthesis speed improved, sound quality improved, and a new voice has been trained.</p><h3 id="_3-10-draw-lottery" tabindex="-1">3. 10-Draw Lottery: <a class="header-anchor" href="#_3-10-draw-lottery" aria-label="Permalink to “3. 10-Draw Lottery:”">​</a></h3><p>Enter &quot;Draw 10&quot; to automatically draw 10 times. The maximum number of draws per draw is 10. Multiple draws are possible. If you haven&#39;t yet participated in the July Yinmei Key lottery, or cannot use Yinmei Core or other modules, please come to the live stream to participate.<br> Prizes include: Live2D Little Flower Bud, Fulin&#39;er, Little Cake, Lanxi VUP Background: Lemonade Memory, Yinmei Key, 300 Points, 800 Points</p><h2 id="ai-yinmei-v2-2-0-may-8-2025" tabindex="-1">Ai Yinmei v2.2.0 [May 8, 2025] <a class="header-anchor" href="#ai-yinmei-v2-2-0-may-8-2025" aria-label="Permalink to “Ai Yinmei v2.2.0 [May 8, 2025]”">​</a></h2><p><strong>1. QQ Bot：</strong>Added Yinmei QQ bot. Multiple bots can be created, allowing interaction with AI in QQ groups and private chats. QQ bots can also interact with livestreams and learn emoticons. QQ bots include singing, drawing, image search, and information search. <strong>2. Desk Pet 2.0：</strong>Added VAD biopsy and voiceprint systems to effectively address issues with speaker echo during microphone conversations. Allows accurate AI chats in complex environments without headphones. <strong>3. Emotion System：</strong>Added 17 emotions: [Bland, Happy, Sad, Angry, Embarrassed, Afraid, Cute, Passionate, Shy, Playful, Gratitude, Affectionate, Confused, Funny, Provocative, Helpless, Curious], adapting the AI&#39;s personality, voice tone, language, and current mood. <strong>4. Added custom configurations：</strong>Customizable active chat operations [including singing, drawing, dancing, changing chat topics, searching for news and weather reports, switching scenes, and changing costumes], voice [singing, accompaniment, main character TTS, assistant TTS], volume adjustment, personality configuration, voice tone configuration, swing action configuration, expression association configuration, language change configuration, singing action configuration, QQ robot configuration, search splitting between DuduckGo and Baidu [Baidu sets cookies], initialization scene configuration, random background music changes, and background image time period switching. <strong>5. Other Feature Optimizations：</strong>AI multi-state real-time monitoring, turning on and off AI hosting, forced language output, [channel splitting, intent, emotion display, and avatar display] in the user list and chat list, shared information settings [improving AI chat comprehensive judgment capabilities] <strong>6. Added multi-tone voice synthesis：</strong>Configure voice changes for different emotions such as anger, happiness, and embarrassment based on voice tone variation schemes <strong>7. Bug Fixes：</strong>Fixed the bug where the &quot;no thank you&quot; feature was displayed when boarding, and eliminated the automatic song switching bug when singing songs</p><p>PS: This update includes 12 configuration options and many minor adjustments, such as refreshing real-time configuration, adjusting volume in four positions, viewing all operation status in real time, and manual user-machine switching.</p><h2 id="ai-yinmei-v2-1-1-2025-2-8" tabindex="-1">Ai Yinmei v2.1.1 [2025-2-8] <a class="header-anchor" href="#ai-yinmei-v2-1-1-2025-2-8" aria-label="Permalink to “Ai Yinmei v2.1.1 [2025-2-8]”">​</a></h2><p><strong>1. Added Configuration：</strong>Long-term memory reset <strong>2. LLM Configuration:</strong><strong>Filter character paragraphs:</strong> Used to filter thought strings similar to DeepSeek R1&#39;s &quot;think&quot; function, and can also filter expressions within () <strong>Skill Prompts:</strong> Added skill prompts for [Singing, Drawing, Chatting, and Dancing]. Word limits can be set in the chat skill settings, and support for random word limits.</p><p><strong>3. Intent Analysis:</strong> Text extraction tool, supports general chat configuration.</p><p><strong>4. Skin Configuration:</strong> Dynamically configure background images. If you set the same scene for the same time period, a random selection can be made. You can set rain, snow, and sunny scenes. The system will then randomly select a scene.</p><p><strong>5. NSFW Detection:</strong> Configure image blocking. Images displayed after NSFW blocking.</p><p><strong>6. Points Configuration:</strong> Points can be configured for [new user registration, liking, singing, drawing, dancing, song switching, regular gifts, RMB sending, and joining a ship]. A point recharge function has also been added, allowing you to recharge points for specific users.</p><h2 id="ai-yinmei-v2-1-0-january-10-2025" tabindex="-1">Ai Yinmei v2.1.0 [January 10, 2025] <a class="header-anchor" href="#ai-yinmei-v2-1-0-january-10-2025" aria-label="Permalink to “Ai Yinmei v2.1.0 [January 10, 2025]”">​</a></h2><p><strong>1. Windows Desktop Pet Pairing:</strong> Added Websocket communication desktop pets, background desktop pet configuration, etc.</p><h2 id="ai-yinmei-v2-0-1-2024-12-21" tabindex="-1">Ai Yinmei v2.0.1 [2024-12-21] <a class="header-anchor" href="#ai-yinmei-v2-0-1-2024-12-21" aria-label="Permalink to “Ai Yinmei v2.0.1 [2024-12-21]”">​</a></h2><p><strong>1. Upgraded Universal Ai Cloud Interface：</strong>Connects to more Ai Cloud services, such as Alibaba Bailian, Zhipu, Tencent Hunyuan, Baichuan Intelligence, Wenxin Yiyan, ChatGpt, ByteDance&#39;s Doubao, and other cloud service platforms. <strong>2. Customizable Welcome Messages for Users Entering Livestreams</strong></p><h2 id="ai-yinmei-v2-0-0-2024-12-6" tabindex="-1">Ai Yinmei v2.0.0 [2024-12-6] <a class="header-anchor" href="#ai-yinmei-v2-0-0-2024-12-6" aria-label="Permalink to “Ai Yinmei v2.0.0 [2024-12-6]”">​</a></h2><p>Epic Architecture Upgrade <strong>1. Upgraded Backend Management System：</strong>Enables better management of Ai Digital Humans. <strong>2. Divergent Thinking：</strong>Enables the use of online memes from QQ group chats to enrich and innovate chat content. <strong>3. Long-Term Memory：</strong>Intelligently recalls Ai memory by evaluating user conversation content. Not all sentences will be recalled. <strong>4. Intent Analysis：</strong>Intelligently determines user intentions, including: chatting, drawing, singing, dancing, searching, searching for images, changing songs, switching scenes, and changing outfits.</p>`,77)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};